  export const LISTA_AERODROMOS_CONSOLIDADOS = Object.values(AERODROMOS_CONSOLIDADOS);
  
  export function buscarAerodromoConsolidadoPorICAO(icao) {
    const codigo = String(icao || '').trim().toUpperCase();
    return AERODROMOS_CONSOLIDADOS[codigo] || null;
  }
  
  // Alias compatível com o App.jsx atual
  export function buscarAerodromoConsolidado(icao) {
    return buscarAerodromoConsolidadoPorICAO(icao);
  }
  
  export default AERODROMOS_CONSOLIDADOS;
  